WITH f9 AS (SELECT MAX(t8."date") AS "a0" FROM v_fct_summary_daily AS t8),
v7 AS MATERIALIZED (SELECT f9.a0 AS v FROM f9),
f21 AS (SELECT MAX(t20."date") AS "a0" FROM v_fct_region_daily AS t20),
v19 AS MATERIALIZED (SELECT f21.a0 AS v FROM f21),
f4 AS MATERIALIZED (SELECT j3."FuelSourceDescriptor" AS "g0", SUM(t2."output_mwh") AS "a0" FROM v_fct_summary_daily AS t2 LEFT JOIN v_dim_duid AS j3 ON j3."DUID" = t2."DUID" WHERE ((t2."date" >= DATE '2026-07-28')) AND ((t2."date" <= DATE '2026-08-11')) AND ((j3."FuelSourceDescriptor" = ('Wind' COLLATE NOCASE))) GROUP BY j3."FuelSourceDescriptor"),
f10 AS MATERIALIZED (SELECT j6."FuelSourceDescriptor" AS "g0", SUM(greatest(t5."mw", 0)) AS "a0" FROM v_fct_summary AS t5 LEFT JOIN v_dim_duid AS j6 ON j6."DUID" = t5."DUID" WHERE ((t5."date" >= DATE '2026-07-28')) AND ((t5."date" <= DATE '2026-08-11')) AND ((j6."FuelSourceDescriptor" = ('Wind' COLLATE NOCASE))) AND ((t5."date" > COALESCE((SELECT v FROM v7), DATE '1899-12-30'))) GROUP BY j6."FuelSourceDescriptor"),
f17 AS (SELECT m16.g0 AS "g0", (COUNT(DISTINCT t11."date") + MAX(CASE WHEN t11."date" IS NULL THEN 1 ELSE 0 END)) AS "a0" FROM v_fct_region_daily AS t11 JOIN (SELECT DISTINCT t15."FuelSourceDescriptor" AS "g0", t15."Region" AS "y" FROM v_dim_duid AS t15 WHERE ((t15."FuelSourceDescriptor" = ('Wind' COLLATE NOCASE)))) AS m16 ON t11."REGIONID" = m16.y WHERE ((t11."date" >= DATE '2026-07-28')) AND ((t11."date" <= DATE '2026-08-11')) AND t11."REGIONID" IN (SELECT t13."Region" AS "k" FROM v_dim_duid AS t13 WHERE ((t13."FuelSourceDescriptor" = ('Wind' COLLATE NOCASE)))) GROUP BY m16.g0),
f27 AS (SELECT m26.g0 AS "g0", (COUNT(DISTINCT row(t18."date", t18."time")) + MAX(CASE WHEN row(t18."date", t18."time") IS NULL THEN 1 ELSE 0 END)) AS "a0" FROM v_fct_region AS t18 JOIN (SELECT DISTINCT t25."FuelSourceDescriptor" AS "g0", t25."Region" AS "y" FROM v_dim_duid AS t25 WHERE ((t25."FuelSourceDescriptor" = ('Wind' COLLATE NOCASE)))) AS m26 ON t18."REGIONID" = m26.y WHERE ((t18."date" >= DATE '2026-07-28')) AND ((t18."date" <= DATE '2026-08-11')) AND ((t18."date" > COALESCE((SELECT v FROM v19), DATE '1899-12-30'))) AND t18."REGIONID" IN (SELECT t23."Region" AS "k" FROM v_dim_duid AS t23 WHERE ((t23."FuelSourceDescriptor" = ('Wind' COLLATE NOCASE)))) GROUP BY m26.g0),
f37 AS (SELECT SUM(f4.a0) AS a0 FROM f4),
f43 AS (SELECT SUM(f10.a0) AS a0 FROM f10)
SELECT q46."series" AS "series", CAST(q46."avg" AS DOUBLE) AS "avg", CAST(q46."share" AS DOUBLE) AS "share" FROM (SELECT s45."FuelSourceDescriptor" AS "series", s45."avg", s45."share" FROM (SELECT * FROM (SELECT k1."FuelSourceDescriptor" AS "FuelSourceDescriptor", (list_sum([f4.a0, (CAST(f10.a0 AS DOUBLE) / 12)]) / NULLIF(list_sum([(CAST(24 AS BIGINT) * f17.a0), (f27.a0 / 12)]), 0)) AS "avg", ((CAST(100 AS BIGINT) * list_sum([f4.a0, (CAST(f10.a0 AS DOUBLE) / 12)])) / NULLIF(list_sum([f37.a0, (CAST(f43.a0 AS DOUBLE) / 12)]), 0)) AS "share" FROM (SELECT f4.g0 AS "FuelSourceDescriptor" FROM f4 UNION SELECT f10.g0 AS "FuelSourceDescriptor" FROM f10) AS k1 LEFT JOIN f4 ON f4.g0 IS NOT DISTINCT FROM k1."FuelSourceDescriptor" LEFT JOIN f10 ON f10.g0 IS NOT DISTINCT FROM k1."FuelSourceDescriptor" LEFT JOIN f17 ON f17.g0 IS NOT DISTINCT FROM k1."FuelSourceDescriptor" LEFT JOIN f27 ON f27.g0 IS NOT DISTINCT FROM k1."FuelSourceDescriptor" LEFT JOIN f37 ON TRUE LEFT JOIN f43 ON TRUE) AS z44 WHERE z44."avg" IS NOT NULL OR z44."share" IS NOT NULL) AS s45) AS q46 ORDER BY q46."avg" DESC NULLS LAST, q46."series" ASC NULLS FIRST
